// Requester entry point, sharing campaigns and approval state with the management workspace.
const easy={admin:false,kind:0,placement:1,design:0,query:'',filter:'전체',photoName:'',editing:false,sizeFirst:false};
const kinds=[['앱 배너','앱의 메인 화면과 팝업에','template',[1,0]],['이벤트·홍보 배너','할인과 새로운 소식을 알릴 때','campaign',[3,1]],['푸시 이미지','알림과 함께 전달할 때','review',[2]],['콘텐츠 이미지','정보를 한 장에 담을 때','assets',[3]]];
const lookNames=['혜택을 한눈에','쿠폰처럼 또렷하게','차분하게 정보 전달'];
const brandColors=[
  {name:'한패스 블루',value:'#1455E8',tone:'dark'},
  {name:'딥 네이비',value:'#173A78',tone:'dark'},
  {name:'스카이',value:'#DCEDFF',tone:'light'},
  {name:'민트',value:'#E2F5EF',tone:'light'},
  {name:'웜 오렌지',value:'#FFE8D4',tone:'light'}
];
const brandGradients=[
  {name:'블루 스카이',value:'linear-gradient(135deg,#1455E8 0%,#45B8FF 100%)',tone:'dark'},
  {name:'소프트 블루',value:'linear-gradient(135deg,#DDEAFF 0%,#E9E2FF 100%)',tone:'light'},
  {name:'민트 블루',value:'linear-gradient(135deg,#E5F8F1 0%,#DCEBFF 100%)',tone:'light'},
  {name:'오렌지 핑크',value:'linear-gradient(135deg,#FFF0D8 0%,#FFE1E7 100%)',tone:'light'}
];
const allBrandColors=[...brandColors,...brandGradients];
function selectedTone(){return allBrandColors.find(x=>x.value===state.color)?.tone||'light'}
function titleLength(){return data().title.replace(/\s/g,'').length}
function easyIssue(){if(!data().title.trim())return {kind:'warn',icon:'!',text:'제목을 입력해 주세요.'};if(titleLength()>34||status(state.lang,state.size)==='글자 넘침')return {kind:'warn',icon:'!',text:'제목이 길어요. 2~3줄 안으로 줄여 주세요.'};return {kind:'ok',icon:'✓',text:'이 규격에 맞게 잘 들어갔어요.'}}
function easyArt(c,look=0){const d=c?.data||defaults;return `<div class="easy-art look-${look}"><span class="ea-brand">hanpass <small>DEMO</small></span><div class="ea-copy"><small>${look===1?'SPECIAL COUPON':'HANPASS BENEFIT'}</small><strong>${esc(d.title)}</strong><p>${esc(d.desc)}</p></div>${d.amount?`<div class="ea-offer"><small>${look===1?'나만의 할인 쿠폰':'지금 받을 수 있는 혜택'}</small><b>${esc(d.amount)}<em>원</em></b><span>${esc(d.coupon)}</span></div>`:''}<footer>${esc(d.period)}<br>샘플 디자인 · 실제 사용 불가</footer></div>`}
const sizePresets=[
  {name:'앱 팝업',use:'앱에서 자세한 행사 내용을 보여줄 때',tag:'POP-UP',title:'버스 할인\n쿠폰 이벤트',benefit:'5,000원'},
  {name:'앱 메인 배너',use:'홈 화면에서 핵심 소식을 알릴 때',tag:'MAIN',title:'신규가입 캐시백 이벤트',benefit:'10,000원'},
  {name:'푸시 이미지',use:'알림과 함께 간단히 전달할 때',tag:'PUSH',title:'한패스 택시\n신규 서비스 오픈',benefit:'NEW'},
  {name:'콘텐츠 이미지',use:'SNS와 콘텐츠에 한 장으로 게시할 때',tag:'CONTENT',title:'해외송금\n수수료 혜택',benefit:'0원'}
];
function sizeArt(i){const p=sizePresets[i],s=sizes[i];return `<div class="preset-art preset-art-${i}" style="aspect-ratio:${s.w}/${s.h}"><span class="preset-brand">hanpass</span><div class="preset-copy"><small>${p.tag} · DEMO</small><strong>${p.title}</strong><p>${i===2?'새로운 소식을 지금 확인하세요':'한패스와 함께하는 특별한 혜택'}</p></div><span class="preset-benefit">${p.benefit}</span><i class="preset-shape"></i></div>`}
function easyShell(body){const focus=state.page==='simple';return `<aside class="sidebar ${focus?'creator-sidebar':''}"><div class="brand">hanpass<span>CREATIVE STUDIO</span></div><div class="workspace">나의 스튜디오</div><button class="nav ${state.page==='home'||state.page==='choose'?'active':''}" data-easy-nav="home">${icon('template')}<span>새 디자인 만들기</span></button><button class="nav ${state.page==='mine'?'active':''}" data-easy-nav="mine">${icon('campaign')}<span>내 작업</span></button><div class="sidebottom"><div class="demo"><b>함께 만드는 브랜드</b>로고와 기본 스타일은<br>관리자가 준비해 두었어요.</div><button class="nav" id="enterAdmin">${icon('settings')}<span>관리자 화면 · 데모</span></button><div class="person"><div class="avatar">민</div><div><b>김민지</b><small style="display:block">마케팅팀 · 요청자</small></div></div></div></aside><main class="main ${focus?'creator-main':''}"><header class="topbar"><span>Hanpass Creative Studio <span style="margin:0 10px">/</span> ${state.page==='mine'?'내 작업':state.page==='simple'?'디자인 만들기':'새 디자인 만들기'}</span><span class="badge blue">직원용 스튜디오</span></header>${body}<p class="easy-disclaimer">프로토타입 · 현재 세션에서만 유지됩니다. 자동 번역·실제 검수 알림·파일 생성은 연결되지 않았어요.</p></main>`}
function workCards(all=false){const rows=campaigns.filter(c=>c.owner==='김민지'&&c.name.includes(easy.query)&&(easy.filter==='전체'||c.status===easy.filter));return rows.length?`<div class="work-grid">${rows.slice(0,all?99:3).map(c=>`<article class="work-card"><button class="work-preview" data-easy-open="${campaigns.indexOf(c)}" aria-label="${esc(c.name)} 이어서 편집">${easyArt(c,c.look||0)}</button><div class="work-info">${badge(c.status)}<h3>${esc(c.name)}</h3><small>${c.date} 마감 · ${c.langs}개 언어 · ${c.sizes}개 규격</small><div class="row"><button class="small" data-easy-open="${campaigns.indexOf(c)}">이어서 편집</button><button class="small ghost" data-easy-copy="${campaigns.indexOf(c)}">복사해서 만들기</button></div></div></article>`).join('')}</div>`:`<div class="card empty"><h2>아직 해당하는 작업이 없어요</h2><p>다른 검색어를 입력하거나 새 디자인을 만들어 보세요.</p><button class="primary sectionspace" data-easy-nav="home">새 디자인 만들기</button></div>`}
function homePage(){return `<div class="easy-page size-home"><div class="size-home-head"><div><span class="eyelabel">NEW DESIGN</span><h1>먼저 만들 크기를 골라 주세요</h1><p>실제 사용 위치와 예시 디자인을 보고 선택하면, 그 크기에 맞는 편집 화면이 열려요.</p></div><span class="size-home-note">자주 쓰는 규격 4개</span></div><div class="size-preset-grid">${sizePresets.map((p,i)=>`<button class="size-preset-card" data-size-start="${i}" aria-label="${p.name} ${sizes[i].w} × ${sizes[i].h}로 만들기"><div class="size-preview">${sizeArt(i)}</div><div class="size-preset-info"><div><span class="size-tag">${p.name}</span><h2>${sizes[i].w} × ${sizes[i].h}px ${sizes[i].example?'<em>예시 규격</em>':''}</h2><p>${p.use}</p></div><span class="size-preset-arrow">→</span></div></button>`).join('')}</div><div class="size-help-row"><span>원하는 크기가 없나요?</span><button class="ghost" id="needDesign">새 규격·디자인 요청 →</button></div><div class="section-heading"><div><h2>이어서 작업하세요</h2><p>이전 디자인을 복사하면 더 빠르게 시작할 수 있어요.</p></div><button class="ghost" data-easy-nav="mine">내 작업 전체 보기 →</button></div>${workCards()}</div>`}
function choicePage(){const s=sizes[easy.placement],p=sizePresets[easy.placement];return `<div class="easy-page"><button class="ghost back" data-easy-nav="home">← 크기 다시 선택</button><div class="easy-heading"><span class="eyelabel">01 크기 선택 완료 <span>— 02 디자인 선택 — 03 내용 편집</span></span><h1>${p.name}, 어떤 디자인으로 만들까요?</h1><p>문구와 이미지는 다음 화면에서 바로 바꿀 수 있어요.</p></div><div class="selected-size"><div class="selected-size-preview">${sizeArt(easy.placement)}</div><div><span>선택한 규격</span><h2>${p.name} · ${s.w} × ${s.h}px</h2><p>${p.use}</p></div><button class="ghost" data-easy-nav="home">변경</button></div><div class="choice-grid">${lookNames.map((n,i)=>`<button class="choice-card ${easy.design===i?'selected':''}" data-look="${i}"><div class="choice-art choice-size-${easy.placement}">${easyArt(null,i)}</div><div class="choice-caption"><div><h3>${n}</h3><small>${['금액을 크게 강조하는 디자인','제목과 혜택을 분리한 디자인','설명과 조건이 많은 행사에'][i]}</small></div><span class="radio-mark">${easy.design===i?'✓':''}</span></div></button>`).join('')}</div><div class="choice-footer"><button class="ghost" id="needDesign">원하는 디자인이 없나요? 도움 요청</button><button class="primary" id="startEasy">이 디자인으로 만들기 →</button></div></div>`}
function simplePage(){const d=data(),issue=easyIssue();return `<div class="creator-heading"><div class="creator-title"><button class="ghost creator-back" data-easy-nav="mine" aria-label="내 작업으로 돌아가기">← 내 작업</button><span class="creator-divider"></span><div><input class="inline-title" id="easyName" aria-label="작업 이름" value="${esc(camp().name)}"><div class="creator-save"><span id="save">✓ ${state.save}</span>${badge(camp().status)}</div></div></div><div class="creator-actions"><button id="saveEasy">임시 저장</button><button class="primary" id="easyReview">검수 전 확인 →</button></div></div><div class="creator-purpose" aria-label="제작 용도 선택"><strong>무엇을 만들까요?</strong><div class="purpose-options">${sizes.map((s,i)=>`<button data-easy-size="${i}" class="${state.size===i?'active':''}"><span>${['앱 팝업','앱 메인','푸시','콘텐츠'][i]}</span><small>${s.w} × ${s.h}${s.example?' · 예시':''}</small></button>`).join('')}</div><div class="creator-steps"><span class="done">✓ 종류</span><span class="active">2 내용·디자인</span><span>3 확인·검수</span></div></div><div class="creator-workbench"><section class="creator-panel creator-copy-panel"><div class="creator-panel-head"><span class="step-number">1</span><div><h2>내용 입력</h2><p>입력하는 즉시 디자인에 반영돼요.</p></div></div><label class="creator-field">제목 <span id="titleCount">${titleLength()} / 34</span><textarea data-field="title" rows="3" placeholder="가장 중요한 소식을 적어 주세요">${esc(d.title)}</textarea></label><button class="suggestion" id="shortSuggestion">✦ 제목을 더 짧게 제안받기 <small>데모</small></button><label class="creator-field">설명 <small>선택</small><textarea data-field="desc" rows="2" placeholder="한 줄로 설명해 주세요">${esc(d.desc)}</textarea></label>${d.amount?`<div class="creator-field-row"><label class="creator-field">혜택 금액 <span>원</span><input data-field="amount" value="${esc(d.amount)}" inputmode="numeric"></label><label class="creator-field">쿠폰 코드 <small>데모</small><input data-field="coupon" value="${esc(d.coupon)}"></label></div>`:''}<label class="creator-field">기간 <input data-field="period" value="${esc(d.period)}"></label><details class="creator-more"><summary>유의사항도 입력할게요</summary><label class="creator-field">필수 안내<textarea data-field="note" rows="3">${esc(d.note)}</textarea></label></details></section><section class="creator-stage"><div class="creator-stage-head"><div><b>${sizes[state.size].name}</b><small>${sizes[state.size].w} × ${sizes[state.size].h}px · ${sizes[state.size].example?'예시 규격':'등록 규격'}</small></div><div class="row"><button class="small" id="easyFit">화면 맞춤</button><button class="small ${state.safe?'active':''}" id="easySafe">안전 영역</button></div></div><div class="simple-paper" id="canvas">${banner()}</div><div class="creator-status ${issue.kind}" id="easyIssue"><b>${issue.icon}</b><span>${issue.text}</span><small>로고와 필수 영역은 자동으로 보호돼요.</small></div><p class="creator-canvas-help">미리보기의 제목을 눌러 바로 수정할 수 있어요.</p></section><aside class="creator-panel creator-style-panel"><div class="creator-panel-head"><span class="step-number">2</span><div><h2>디자인 선택</h2><p>승인된 범위 안에서만 바뀌어요.</p></div></div><div class="creator-section"><h3>구성</h3><div class="layout-options">${lookNames.map((n,i)=>`<button data-easy-look="${i}" class="${(camp().look||0)===i?'selected':''}"><span class="layout-mini look-mini-${i}"><i></i><i></i><i></i></span><b>${n}</b>${(camp().look||0)===i?'<em>✓</em>':''}</button>`).join('')}</div></div><div class="creator-section"><div class="row between"><h3>한패스 컬러</h3><small>기본 5색</small></div><div class="color-options">${brandColors.map(c=>`<button data-easy-color="${esc(c.value)}" class="${state.color===c.value?'selected':''}" aria-label="${c.name}" title="${c.name}" style="background:${c.value}">${state.color===c.value?'<span>✓</span>':''}</button>`).join('')}</div><div class="row between gradient-label"><h3>그라데이션</h3><small>승인 조합</small></div><div class="gradient-options">${brandGradients.map(c=>`<button data-easy-color="${esc(c.value)}" class="${state.color===c.value?'selected':''}" aria-label="${c.name}" title="${c.name}" style="background:${c.value}">${state.color===c.value?'<span>✓</span>':''}</button>`).join('')}</div></div><div class="creator-section"><h3>이미지</h3><button class="asset-drop ${state.asset?'has-file':''}" id="easyPhoto"><span>${state.asset?'✓':'＋'}</span><div><b>${state.asset?(easy.photoName||'선택한 이미지'):'내 이미지 선택'}</b><small>${state.asset?'클릭하여 다른 이미지로 교체':'PNG · JPG · 데모 로컬 적용'}</small></div></button>${state.asset?'<button class="remove-photo" id="removePhoto">이미지 제거</button>':''}<input type="file" id="easyFile" accept="image/*" hidden></div><div class="creator-locks"><span>🔒 로고</span><span>🔒 글꼴</span><span>🔒 안전 여백</span></div><button class="ghost creator-help" id="easyHelp">이 디자인에 도움이 필요해요 →</button></aside></div>`}
function checkPage(){const issue=easyIssue();return `<div class="easy-page"><button class="ghost back" data-easy-nav="simple">← 편집으로 돌아가기</button><div class="easy-heading"><span class="eyelabel">03 확인·검수</span><h1>이제 마지막으로 확인해 주세요</h1><p>추가로 필요한 언어와 용도를 선택하고 검수를 요청하세요.</p></div><div class="easy-check-grid"><div class="card"><h2>${esc(camp().name)}</h2><div class="check-art">${easyArt(camp(),camp().look||0)}</div><div class="callout ${issue.kind==='warn'?'warn':''}">${issue.icon} ${issue.kind==='warn'?'문구 수정 필요 · 편집 화면에서 제목을 줄여 주세요.':'기본 디자인 확인 완료 · 데모 검사'}</div></div><div class="card"><h2>어떤 언어가 필요한가요?</h2><p class="muted">한국어만 필요하면 그대로 진행하세요.</p><div class="chips">${langs.slice(0,12).map((l,i)=>`<label><input type="checkbox" data-checklang="${i}" ${activeLangs().includes(i)?'checked':''}> ${l}</label>`).join('')}</div><h2 class="sectionspace">함께 만들 용도가 있나요?</h2><div class="chips">${sizes.slice(0,4).map((s,i)=>`<label><input type="checkbox" data-checksize="${i}" ${activeSizes().includes(i)?'checked':''}> ${s.name}<small style="display:block">${s.w} × ${s.h}${s.example?' · 예시':''}</small></label>`).join('')}</div><div class="callout" id="easyCount">${activeLangs().length}개 언어 × ${activeSizes().length}개 규격 = ${totalResults()}개 결과물</div><p class="footnote">다국어 결과물은 번역 검수를 거쳐야 최종 승인할 수 있어요.</p><label class="field sectionspace">검수자에게 전할 내용<textarea id="easyReviewNote" placeholder="확인했으면 하는 내용을 적어 주세요"></textarea></label><button class="primary" style="width:100%" id="sendEasyReview">검수 요청하기</button></div></div></div>`}
function donePage(){return `<div class="easy-page"><div class="submitted card"><span class="submitted-icon">✓</span><h1>검수를 요청했어요</h1><p>${esc(camp().name)}</p><div class="callout">데모 요청이 저장됐어요. 실제 알림은 발송되지 않습니다.</div><div class="review-steps"><span>✓ 제작 완료</span><span>◷ 검수 대기</span><span>승인 후 다운로드</span></div><div class="row"><button data-easy-nav="mine">내 작업으로</button><button class="primary" id="seeApproval">검수·다운로드 확인</button></div></div></div>`}
const standardBanner=banner;banner=function(){return standardBanner().replace('class="banner ', 'class="banner easy-look-'+(camp().look||0)+' '+(selectedTone()==='dark'?'tone-dark ':'')+(state.asset?'has-asset ':' '))};
const detailedRender=render;
const detailedNavigate=navigate;
navigate=function(p){if(!easy.admin){if(p==='campaigns')p='home';if(p==='edit')p='simple';if(p==='new')p='home';if(['templates','settings','inbox'].includes(p)){notify('관리자 화면에서 관리할 수 있어요.');p='home'}}detailedNavigate(p)};
function selectWork(c){camp().workflow=snapshot();state.campaign=campaigns.indexOf(c);Object.assign(state,c.workflow||initialWorkflow(c));easy.kind=c.kind??easy.kind;easy.design=c.look||0;if(!allBrandColors.some(x=>x.value===state.color))state.color='#DCEDFF';navigate('simple')}
function createEasy(copy){const d=copy?{...copy.data}:{...defaults};const c={name:copy?copy.name+' (복사)':'새 '+kinds[easy.kind][0],owner:'김민지',date:'2026-09-30',status:'작업 중',langs:1,sizes:1,languageIds:[0],sizeIds:[easy.placement],kind:easy.kind,look:easy.design,data:d};campaigns.push(c);selectWork(c)}
render=function(){const routes={home:homePage,choose:choicePage,simple:simplePage,check:checkPage,submitted:donePage,mine:()=>`<div class="easy-page"><div class="section-heading"><div><h1>내 작업</h1><p>만들던 디자인을 이어서 편집하거나 복사해 사용하세요.</p></div><button class="primary" data-easy-nav="home">＋ 새 디자인 만들기</button></div><div class="filters"><input id="easySearch" placeholder="내 작업 검색" value="${esc(easy.query)}" aria-label="내 작업 검색"><select id="easyFilter">${['전체','작업 중','검수 대기','수정 필요','승인 완료'].map(x=>`<option ${x===easy.filter?'selected':''}>${x}</option>`).join('')}</select></div>${workCards(true)}</div>`};if(!easy.admin&&routes[state.page]){$('#app').innerHTML=easyShell(routes[state.page]());bindEasy()}else{detailedRender();if(easy.admin){$('.sidebar .workspace').textContent='제작 관리';$('.sidebar .sidebottom').insertAdjacentHTML('afterbegin','<button class="nav" id="leaveAdmin">← 직원용 스튜디오</button>');$('#leaveAdmin').onclick=()=>{easy.admin=false;state.role='요청자';navigate('home')}}else{const body=$('.main');const oldSidebar=$('.sidebar');oldSidebar.outerHTML=easyShell('').split('<main')[0];$('#enterAdmin').onclick=enterAdmin;$$('[data-easy-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.easyNav));const role=$('#role');if(role)role.parentElement.innerHTML='<span class="badge blue">직원용 스튜디오</span>';const header=$('.pagehead');if(header)header.insertAdjacentHTML('afterbegin','<button class="ghost" id="returnSimple">← 간편 편집으로</button>');if($('#returnSimple'))$('#returnSimple').onclick=()=>navigate('simple')}}};
function enterAdmin(){easy.admin=true;state.role='디자이너';navigate('campaigns')}
function bindEasy(){$$('[data-easy-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.easyNav));$('#enterAdmin').onclick=enterAdmin;$$('[data-size-start]').forEach(b=>b.onclick=()=>{easy.placement=+b.dataset.sizeStart;easy.kind=[0,0,2,3][easy.placement];easy.design=0;easy.editing=false;easy.sizeFirst=true;navigate('choose')});$$('[data-kind]').forEach(b=>b.onclick=()=>{easy.kind=+b.dataset.kind;easy.placement=kinds[easy.kind][3][0];easy.editing=false;easy.sizeFirst=false;navigate('choose')});$$('[data-place]').forEach(b=>b.onclick=()=>{easy.placement=+b.dataset.place;render()});$$('[data-look]').forEach(b=>b.onclick=()=>{easy.design=+b.dataset.look;render()});$$('[data-easy-open]').forEach(b=>b.onclick=()=>selectWork(campaigns[+b.dataset.easyOpen]));$$('[data-easy-copy]').forEach(b=>b.onclick=()=>{const c=campaigns[+b.dataset.easyCopy];easy.design=c.look||0;easy.placement=c.sizeIds?.[0]||0;createEasy(c);notify('원본을 유지하고 새 작업을 만들었어요.')});const on=(id,fn,event='onclick')=>{if($('#'+id))$('#'+id)[event]=fn};
$$('[data-easy-size]').forEach(b=>b.onclick=()=>{state.size=+b.dataset.easySize;easy.placement=state.size;camp().sizeIds=[state.size];camp().sizes=1;state.approved={};state.requested=false;render()});
$$('[data-easy-look]').forEach(b=>b.onclick=()=>{easy.design=+b.dataset.easyLook;camp().look=easy.design;state.approved={};state.requested=false;render()});
$$('[data-easy-color]').forEach(b=>b.onclick=()=>{state.color=b.dataset.easyColor;state.approved={};state.requested=false;render()});
on('easySafe',()=>{state.safe=!state.safe;render()});
on('startEasy',()=>{if(easy.editing){camp().look=easy.design;state.color=['#dcedff','#e5f1ed','#fff0d7'][easy.design];state.size=easy.placement;camp().sizeIds=[easy.placement];camp().sizes=1;state.approved={};state.requested=false;camp().status='작업 중';navigate('simple')}else createEasy()});on('changeLook',()=>{easy.editing=true;easy.placement=state.size;navigate('choose')});on('easyName',e=>{camp().name=e.target.value},'oninput');on('easySearch',e=>{easy.query=e.target.value;render();$('#easySearch').focus()},'oninput');on('easyFilter',e=>{easy.filter=e.target.value;render()},'onchange');
$$('[data-field]').forEach(e=>e.oninput=()=>{state.scope='common';saveChange(e.dataset.field,e.value);const info=easyIssue(),issue=$('#easyIssue'),counter=$('#titleCount');if(issue){issue.className='creator-status '+info.kind;issue.innerHTML=`<b>${info.icon}</b><span>${info.text}</span><small>로고와 필수 영역은 자동으로 보호돼요.</small>`}if(counter)counter.textContent=titleLength()+' / 34';wireBanner()});function wireBanner(){if($('.btitle')){$('.btitle').setAttribute('tabindex','0');$('.btitle').setAttribute('role','button');$('.btitle').setAttribute('aria-label','제목 수정');$('.btitle').onclick=()=>{$('[data-field="title"]').focus();$('[data-field="title"]').select()};$('.btitle').onkeydown=e=>{if(e.key==='Enter')$('.btitle').onclick()}}}wireBanner();
on('shortSuggestion',()=>{const title=camp().data.short||'한패스와 함께하는 특별한 혜택';confirmBox('이 문구로 바꿔 볼까요?',esc(title)+' · 미리 준비된 데모 제안입니다.',()=>{state.scope='common';saveChange('title',title);render()},'문구 적용')});function applyEasyImage(f){if(!f)return;if(!f.type.startsWith('image/'))return notify('이미지 파일을 선택해 주세요.');if(state.asset?.startsWith?.('blob:'))URL.revokeObjectURL(state.asset);state.asset=URL.createObjectURL(f);easy.photoName=f.name;state.approved={};state.requested=false;render();notify('이미지를 미리보기에 적용했어요. 외부 서버에는 업로드하지 않아요.')}on('easyPhoto',()=>$('#easyFile').click());on('easyFile',e=>applyEasyImage(e.target.files[0]),'onchange');on('removePhoto',()=>{if(state.asset?.startsWith?.('blob:'))URL.revokeObjectURL(state.asset);state.asset=null;easy.photoName='';render();notify('이미지를 제거했어요.')});const drop=$('.asset-drop');if(drop){drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging')};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');applyEasyImage(e.dataTransfer.files[0])}}on('easyFit',()=>{state.zoom=100;render()});on('saveEasy',()=>{camp().workflow=snapshot();notify('현재 세션의 내 작업에 저장했어요.')});on('easyReview',()=>{if(!camp().name.trim()||!camp().data.title.trim())return notify('작업 이름과 제목을 입력해 주세요.');navigate('check')});
const help=()=>{navigate('request')};on('easyHelp',help);on('needDesign',help);for(const [attr,property,count]of [['checklang','languageIds','langs'],['checksize','sizeIds','sizes']])$$('[data-'+attr+']').forEach(b=>b.onchange=()=>{const ids=property==='languageIds'?activeLangs():activeSizes();if(!b.checked&&ids.length===1){b.checked=true;return notify('하나 이상 선택해 주세요.')}camp()[property]=b.checked?[...ids,+b.dataset[attr]]:ids.filter(i=>i!==+b.dataset[attr]);camp()[count]=camp()[property].length;$('#easyCount').textContent=`${activeLangs().length}개 언어 × ${activeSizes().length}개 규격 = ${totalResults()}개 결과물`});on('sendEasyReview',()=>{if(easyIssue().kind==='warn')return notify('제목 길이를 수정한 다음 요청해 주세요.');state.requested=true;camp().status='검수 대기';state.history.unshift('직접 제작 후 검수 요청 · '+($('#easyReviewNote').value||'추가 의견 없음'));camp().workflow=snapshot();navigate('submitted')});on('seeApproval',()=>navigate('download'));
}
state.page=['','campaigns','edit','new','home'].includes(location.hash.slice(1))?'home':state.page;if(['templates','settings','inbox'].includes(state.page))state.page='home';render();
